mutation discountAutomaticAppUpdate($automaticAppDiscount: DiscountAutomaticAppInput!, $id: ID!) {
  discountAutomaticAppUpdate(automaticAppDiscount: $automaticAppDiscount, id: $id) {
    automaticAppDiscount {
      title
      context {
        ... on DiscountCustomerSegments {
          segments {
            id
          }
        }
      }
    }
    userErrors {
      field
      message
    }
  }
}

mutation discountAutomaticAppUpdate($automaticAppDiscount: DiscountAutomaticAppInput!, $id: ID!) {
  discountAutomaticAppUpdate(automaticAppDiscount: $automaticAppDiscount, id: $id) {
    automaticAppDiscount {
      title
      startsAt
      endsAt
      status
    }
    userErrors {
      field
      message
    }
  }
}

mutation discountAutomaticAppUpdate($automaticAppDiscount: DiscountAutomaticAppInput!, $id: ID!) {
  discountAutomaticAppUpdate(automaticAppDiscount: $automaticAppDiscount, id: $id) {
    automaticAppDiscount {
      title
      status
      appDiscountType {
        appKey
        functionId
      }
    }
    userErrors {
      field
      message
    }
  }
}

inputTypesSdl.DiscountCombinesWithInput:
input DiscountCombinesWithInput {
  productDiscounts: Boolean
  orderDiscounts: Boolean
  shippingDiscounts: Boolean
}

inputTypesSdl.DiscountContextInput:
input DiscountContextInput {
  all: DiscountBuyerSelection
  customers: DiscountCustomersInput
  customerSegments: DiscountCustomerSegmentsInput
}
